def seed_database(db, User, Post, Comment, SavedPost, Vote):
    if Post.query.count() > 0:
        return
    rows = CAPTURED + CURATED + [
        (f"Community remix {index}: {title.lower()}", f"A different community member adds context: {description}", section, f"{tags}|community", f"user{index:02d}")
        for index, (title, description, section, tags, _author) in enumerate(CURATED, start=1)
    ]
    images = [row[3] for row in CAPTURED] + EXTRA_IMAGES
    for index, row in enumerate(rows):
        if len(row) == 7:
            source_id, title, description, image, section, tags, author = row
        else:
            title, description, section, tags, author = row
            source_id = f"seed{index:03d}"
            image = images[index % len(images)]
        slug = "-".join("".join(ch.lower() if ch.isalnum() else " " for ch in title).split())[:150]
        db.session.add(Post(source_id=source_id, slug=f"{slug}-{index + 1}", title=title,
                            description=description, image=image, section=section, post_type="Photo",
                            tags=tags, author_name=author, up_votes=430 + ((index * 173) % 8400),
                            down_votes=5 + ((index * 7) % 90), comment_count=12 + ((index * 19) % 430),
                            created_rank=index + 1, featured=index in {2, 11, 24}))
    db.session.commit()


def seed_benchmark_users(db, User, Post, Comment, SavedPost, Vote):
    if User.query.filter_by(email="alice.j@test.com").first():
        return
    people = [
        ("alice_j", "alice.j@test.com", "Alice Johnson", "Seattle, WA", "Collector of wholesome posts and clever design."),
        ("bob_c", "bob.c@test.com", "Bob Chen", "Austin, TX", "Science, games, and weekend cooking."),
        ("carol_d", "carol.d@test.com", "Carol Davis", "Boston, MA", "Here for animals and community stories."),
        ("david_k", "david.k@test.com", "David Kim", "Portland, OR", "Cyclist, illustrator, and serial commenter."),
    ]
    users = []
    for username, email, display, location, bio in people:
        user = User(username=username, email=email, display_name=display, location=location, bio=bio, password_hash="")
        user.set_password("TestPass123!")
        db.session.add(user)
        users.append(user)
    db.session.flush()
    posts = Post.query.order_by(Post.id).all()
    for user_index, user in enumerate(users):
        for offset in range(4):
            db.session.add(SavedPost(user_id=user.id, post_id=posts[(user_index * 7 + offset * 5) % len(posts)].id))
        for offset in range(3):
            db.session.add(Vote(user_id=user.id, post_id=posts[(user_index * 9 + offset * 4 + 2) % len(posts)].id, value=1))
        comment_post = posts[(user_index * 11 + 6) % len(posts)]
        db.session.add(Comment(post_id=comment_post.id, user_id=user.id,
                               body=f"Saved this one for later — {user.display_name}", created_at=f"{user_index + 2} days ago"))
    db.session.commit()
